  const undetermined2 = c && typeof c.undetermined === "number" ? c.undetermined : markers.reduce((n, m) => n + (m && typeof m.count === "number" ? m.count : 1), 0);
  const reasons = [...new Set(markers.map((m) => m && m.reason).filter(Boolean))];
